_VALID_DATE_STATUSES = {"available", "landed", "cancelled", "delayed", "flying", "on time"}
raw_dates = json.loads(r["dates_json"] or "{}")
# Strip unknown cabin keys from prices/available_seats in each date
clean_dates: Dict[str, Any] = {}
for dt, info in raw_dates.items():
    if isinstance(info, dict):
        # Coerce unknown flight-date statuses to 'available'
        if info.get("status") not in _VALID_DATE_STATUSES:
            info["status"] = "available"
        for key in ("prices", "available_seats"):
            if key in info and isinstance(info[key], dict):
                info[key] = {k: v for k, v in info[key].items() if k in _TAU2_CABINS}
    clean_dates[dt] = info

